  tool_uuid_generator_faq_a5:
    'UUID v4 : 36 caractères avec tirets, hex minuscules. ULID : 26 caractères Crockford Base32 majuscules, sans tirets.',
  tool_uuid_generator_faq_q1: 'UUID v4 vs ULID — lequel choisir ?',
